mapper.sql:
WHERE tenant_id = #{tenantId}


    AND source_type = #{sourceType}



    AND report_code = #{reportCode}



    AND datasource_code = #{datasourceCode}



    AND stage_code = #{stageCode}



    AND biz_date = #{bizDate}



    AND query_date_start >= #{queryDateStart}



    AND query_date_end <= #{queryDateEnd}



    AND result_status = #{status}



    AND logical_object_hits_json LIKE CONCAT('%', #{logicalObjectType}, '%')



    AND access_channel = #{accessChannel}



    AND target_engine = #{engine}



    AND submitted_by = #{submittedBy}



    AND trace_id = #{traceId}



    AND parse_task_id = #{parseTaskId}



    AND submitted_at >= #{submittedStart}



    AND submitted_at <= #{submittedEnd}

mapper.select:
SELECT 
FROM sql_parse_history
WHERE batch_key = #{batchKey}
  AND sql_fingerprint = #{sqlFingerprint}
ORDER BY submitted_at DESC, parse_history_id DESC
LIMIT 1

SELECT 
FROM sql_parse_history


ORDER BY ${orderByClause}
LIMIT #{offset}, #{limit}
